begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users (id,email,raw_user_meta_data) values
 ('10000000-0000-0000-0000-000000000001','sharing-author@test.local','{"display_name":"Author"}'),
 ('10000000-0000-0000-0000-000000000002','sharing-pub1@test.local','{"display_name":"P1","account_kind":"publisher","publisher_kind":"publishing_house"}'),
 ('10000000-0000-0000-0000-000000000003','sharing-pub2@test.local','{"display_name":"P2","account_kind":"publisher","publisher_kind":"publishing_house"}'),
 ('10000000-0000-0000-0000-000000000004','sharing-reader@test.local','{"display_name":"Reader"}');
update public.profiles set author_enabled=true where id='10000000-0000-0000-0000-000000000001';
insert into public.works (id,title,owner_id,source,visibility) values ('20000000-0000-0000-0000-000000000001','Work','10000000-0000-0000-0000-000000000001','author','public');
insert into public.manuscript_versions (id,work_id,storage_path,sha256,byte_size,page_count) values ('30000000-0000-0000-0000-000000000001','20000000-0000-0000-0000-000000000001','test/file.pdf',repeat('a',64),100,1);
insert into public.calls (id,publisher_id,title,opens_at,accepted_languages) values
 ('40000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000002','P1',now(),'{ro}'),
 ('40000000-0000-0000-0000-000000000002','10000000-0000-0000-0000-000000000003','P2',now(),'{ro}');
insert into public.submissions (id,author_id,work_id,version_id,publisher_id,call_id,contact_email,contact_phone,rights_declared_at,contact_consent_at,accepted_policy,idempotency_key) values
 ('50000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001','20000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000002','40000000-0000-0000-0000-000000000001','a@test.local','123',now(),now(),'{"sharing_policy":"synopsis_and_excerpt_approval"}',gen_random_uuid()),
 ('50000000-0000-0000-0000-000000000002','10000000-0000-0000-0000-000000000001','20000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000003','40000000-0000-0000-0000-000000000002','a@test.local','123',now(),now(),'{"sharing_policy":"synopsis_and_excerpt_approval"}',gen_random_uuid());
set local role authenticated;
set local request.jwt.claims to '{"sub":"10000000-0000-0000-0000-000000000001","role":"authenticated"}';
select set_config('test.excerpt',public.create_excerpt('20000000-0000-0000-0000-000000000001','excerpt','own_work',null,'First exact text','public')::text,true);
select set_config('test.version',(select id::text from public.text_versions where excerpt_id=current_setting('test.excerpt')::uuid),true);
select set_config('test.request',public.request_sharing(current_setting('test.version')::uuid)::text,true);
select is((select count(*) from public.sharing_decisions where request_id=current_setting('test.request')::uuid),2::bigint,'both applicable submissions require approval');
select throws_ok($$select public.publish_excerpt(current_setting('test.version')::uuid)$$,'P0001','approvals_required','pending approvals prevent publication');
set local request.jwt.claims to '{"sub":"10000000-0000-0000-0000-000000000004","role":"authenticated"}';
select ok(not public.can_view_content(current_setting('test.excerpt')::uuid),'unapproved text is hidden from readers');
select is((select count(*) from public.text_versions where id=current_setting('test.version')::uuid),0::bigint,'unapproved exact text is inaccessible to readers');
select is(jsonb_array_length(public.sharing_workspace()->'requests'),0,'another reader cannot see private requests');
select throws_ok($$select public.decide_sharing(current_setting('test.request')::uuid,'50000000-0000-0000-0000-000000000001',true)$$,'42501',null,'another reader cannot decide');
set local request.jwt.claims to '{"sub":"10000000-0000-0000-0000-000000000002","role":"authenticated"}';
select is((select count(*) from public.sharing_decisions where request_id=current_setting('test.request')::uuid),1::bigint,'publication cannot see another publication submission decision');
select is(jsonb_array_length((public.sharing_workspace()->'requests'->0)->'decisions'),1,'workspace does not expose another publication decision');
select lives_ok($$select public.decide_sharing(current_setting('test.request')::uuid,'50000000-0000-0000-0000-000000000001',true)$$,'first publication approves');
select lives_ok($$select public.decide_sharing(current_setting('test.request')::uuid,'50000000-0000-0000-0000-000000000001',true)$$,'repeated decision is idempotent');
reset role;
select is((select count(*) from public.domain_events where kind='sharing_decided' and subject_id=current_setting('test.request')::uuid),1::bigint,'repeating a decision emits one event');
update public.submissions set status='on_hold' where id='50000000-0000-0000-0000-000000000002';
set local role authenticated;
set local request.jwt.claims to '{"sub":"10000000-0000-0000-0000-000000000001","role":"authenticated"}';
select throws_ok($$select public.publish_excerpt(current_setting('test.version')::uuid)$$,'P0001','approvals_required','on hold still restricts');
reset role;
update public.submissions set status='selected' where id='50000000-0000-0000-0000-000000000002';
set local role authenticated;
select throws_ok($$select public.publish_excerpt(current_setting('test.version')::uuid)$$,'P0001','approvals_required','selected still restricts');
reset role;
update public.submissions set status='withdrawn' where id='50000000-0000-0000-0000-000000000002';
set local role authenticated;
select lives_ok($$select public.publish_excerpt(current_setting('test.version')::uuid)$$,'withdrawal ends restriction');
set local request.jwt.claims to '{"sub":"10000000-0000-0000-0000-000000000004","role":"authenticated"}';
select ok(public.can_view_content(current_setting('test.excerpt')::uuid),'published version visible to reader');
select public.set_follow('10000000-0000-0000-0000-000000000001',true);
select is((select x->>'body' from public.feed_page() x where x->>'id'=current_setting('test.excerpt')),'First exact text','published excerpt appears in followed feed');
reset role;
update public.submissions set status='submitted' where id='50000000-0000-0000-0000-000000000002';
set local role authenticated;
select ok(public.can_view_content(current_setting('test.excerpt')::uuid),'later submission does not hide published version');
set local request.jwt.claims to '{"sub":"10000000-0000-0000-0000-000000000001","role":"authenticated"}';
reset role;
insert into storage.objects(bucket_id,name) values ('excerpt-images','10000000-0000-0000-0000-000000000001/image.png');
set local role authenticated;
select throws_ok($$insert into storage.objects(bucket_id,name) values ('excerpt-images','10000000-0000-0000-0000-000000000004/image.png')$$,'42501',null,'cannot upload in another account folder');
select set_config('test.image_version',public.revise_excerpt(current_setting('test.excerpt')::uuid,'First exact text','10000000-0000-0000-0000-000000000001/image.png')::text,true);
select isnt(current_setting('test.image_version'), current_setting('test.version'), 'image change creates a new version');
select public.request_sharing(current_setting('test.image_version')::uuid);
select throws_ok($$select public.publish_excerpt(current_setting('test.image_version')::uuid)$$,'P0001','approvals_required','image revision requires fresh approval');
select throws_ok($$select public.revise_excerpt(current_setting('test.excerpt')::uuid,'text','10000000-0000-0000-0000-000000000004/image.png')$$,'42501',null,'revision refuses another account image');
select set_config('test.edited',public.revise_excerpt(current_setting('test.excerpt')::uuid,'Edited text')::text,true);
select set_config('test.request2',public.request_sharing(current_setting('test.edited')::uuid)::text,true);
select throws_ok($$select public.publish_excerpt(current_setting('test.edited')::uuid)$$,'P0001','approvals_required','old approvals do not cover edited text');
set local request.jwt.claims to '{"sub":"10000000-0000-0000-0000-000000000004","role":"authenticated"}';
select ok(public.can_view_content(current_setting('test.excerpt')::uuid),'old version remains visible during revision');
set local request.jwt.claims to '{"sub":"10000000-0000-0000-0000-000000000002","role":"authenticated"}';
select throws_ok($$select public.create_excerpt('20000000-0000-0000-0000-000000000001','excerpt','own_book',null,'Book quote','public')$$,'42501',null,'own book quote requires confirmed association');
select set_config('test.quote',public.create_excerpt('20000000-0000-0000-0000-000000000001','excerpt','received_manuscript','50000000-0000-0000-0000-000000000001','Quote','public')::text,true);
select set_config('test.quote_version',(select id::text from public.text_versions where excerpt_id=current_setting('test.quote')::uuid),true);
select set_config('test.quote_request',public.request_sharing(current_setting('test.quote_version')::uuid)::text,true);
select throws_ok($$select public.publish_excerpt(current_setting('test.quote_version')::uuid)$$,'P0001','approvals_required','received quote needs author approval');
reset role;
update public.submissions set status='rejected' where id='50000000-0000-0000-0000-000000000001';
set local role authenticated;
select throws_ok($$select public.create_excerpt('20000000-0000-0000-0000-000000000001','excerpt','received_manuscript','50000000-0000-0000-0000-000000000001','Quote','public')$$,'42501',null,'received quote requires active submission');
reset role;
update public.submissions set status='submitted' where id='50000000-0000-0000-0000-000000000001';
set local role authenticated;
set local request.jwt.claims to '{"sub":"10000000-0000-0000-0000-000000000004","role":"authenticated"}';
select throws_ok($$select public.author_decide_quote(current_setting('test.quote_request')::uuid,true)$$,'42501',null,'another reader cannot approve the quote');
set local request.jwt.claims to '{"sub":"10000000-0000-0000-0000-000000000001","role":"authenticated"}';
select lives_ok($$select public.author_decide_quote(current_setting('test.quote_request')::uuid,true)$$,'author approves exact quote');
set local request.jwt.claims to '{"sub":"10000000-0000-0000-0000-000000000002","role":"authenticated"}';
select throws_ok($$select public.publish_excerpt(current_setting('test.quote_version')::uuid)$$,'P0001','approvals_required','other publisher approval still applies');
reset role;
update public.submissions set status='rejected' where id='50000000-0000-0000-0000-000000000002';
set local role authenticated;
select lives_ok($$select public.publish_excerpt(current_setting('test.quote_version')::uuid)$$,'rejection ends other publisher restriction');
reset role;
update public.works set is_published=true where id='20000000-0000-0000-0000-000000000001';
insert into public.work_publishers(work_id,publisher_id,status) values ('20000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000002','confirmed');
set local role authenticated;
select set_config('test.book',public.create_excerpt('20000000-0000-0000-0000-000000000001','excerpt','own_book',null,'Book quote','public')::text,true);
select set_config('test.book_version',(select id::text from public.text_versions where excerpt_id=current_setting('test.book')::uuid),true);
select lives_ok($$select public.request_sharing(current_setting('test.book_version')::uuid)$$,'confirmed own book can be quoted');
reset role;
update public.work_publishers set status='declined' where work_id='20000000-0000-0000-0000-000000000001' and publisher_id='10000000-0000-0000-0000-000000000002';
set local role authenticated;
select throws_ok($$select public.publish_excerpt(current_setting('test.book_version')::uuid)$$,'42501',null,'own-book publication still requires confirmed association');
set local request.jwt.claims to '{"sub":"10000000-0000-0000-0000-000000000001","role":"authenticated"}';
select set_config('test.followers',public.create_excerpt('20000000-0000-0000-0000-000000000001','excerpt','own_work',null,'Followers only','followers')::text,true);
select set_config('test.fversion',(select id::text from public.text_versions where excerpt_id=current_setting('test.followers')::uuid),true);
select public.request_sharing(current_setting('test.fversion')::uuid);
reset role;
update public.submissions set status='rejected' where id='50000000-0000-0000-0000-000000000001';
set local role authenticated;
select public.publish_excerpt(current_setting('test.fversion')::uuid);
set local request.jwt.claims to '{"sub":"10000000-0000-0000-0000-000000000004","role":"authenticated"}';
select throws_ok($$select public.create_post(null,null,null,current_setting('test.followers')::uuid)$$,'42501',null,'followers-only excerpts cannot be reshared');
set local request.jwt.claims to '{"sub":"10000000-0000-0000-0000-000000000001","role":"authenticated"}';
select set_config('test.late',public.create_excerpt('20000000-0000-0000-0000-000000000001','excerpt','own_work',null,'Awaiting publication','public')::text,true);
select set_config('test.late_version',(select id::text from public.text_versions where excerpt_id=current_setting('test.late')::uuid),true);
select public.request_sharing(current_setting('test.late_version')::uuid);
reset role;
insert into public.submissions (id,author_id,work_id,version_id,publisher_id,call_id,contact_email,contact_phone,rights_declared_at,contact_consent_at,accepted_policy,idempotency_key)
values ('50000000-0000-0000-0000-000000000003','10000000-0000-0000-0000-000000000001','20000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000003','40000000-0000-0000-0000-000000000002','a@test.local','123',now(),now(),'{"sharing_policy":"synopsis_and_excerpt_approval"}',gen_random_uuid());
set local role authenticated;
select throws_ok($$select public.publish_excerpt(current_setting('test.late_version')::uuid)$$,'P0001','approvals_required','submission added before publication requires approval');
select lives_ok($$select public.request_sharing(current_setting('test.late_version')::uuid)$$,'request refresh includes newly applicable submission');
set local request.jwt.claims to '{"sub":"10000000-0000-0000-0000-000000000004","role":"authenticated"}';
select ok(public.can_view_content(current_setting('test.excerpt')::uuid),'new submission does not hide existing public version');
select * from finish();
rollback;
